B.bx_=new A.d6("Kirli do\u011fum ortam\u0131, g\xf6bek dezenfeksiyonu eksikli\u011fi",B.apW)
B.b8N=s(["Gebe d\xfcve/inek kondisyon ve mineral program\u0131; BVD a\u015f\u0131s\u0131 ve PI hayvan taramas\u0131.","Zay\u0131f do\u011fana ilk saatte kolostrum (gerekirse sonda) ve \u0131s\u0131tma."],t.s)
B.bxj=new A.d6("Annenin beslenme/hastal\u0131\u011f\u0131, ikiz, BVD gibi enfeksiyonlar",B.b8N)
B.baQ=s(["D\xfcveler hedef canl\u0131 a\u011f\u0131rl\u0131kta tohumlans\u0131n; kolay do\u011fum bo\u011fas\u0131 se\xe7ilsin.","Do\u011fum ekibine m\xfcdahale zamanlamas\u0131 e\u011fitimi."],t.s)
B.bwZ=new A.d6("\u0130ri buza\u011f\u0131, erken tohumlanm\u0131\u015f/k\xfc\xe7\xfck d\xfcve, yanl\u0131\u015f duru\u015f",B.baQ)
B.b8n=s(["Do\u011fumlar\u0131n g\xf6zetimi; uzayan do\u011fuma zaman\u0131nda m\xfcdahale.","Abort/\xf6l\xfc do\u011fumlardan laboratuvar \xf6rne\u011fi."],t.s)
B.bx9=new A.d6("G\xfc\xe7 do\u011fum, enfeksiyon (BVD, Neospora, Leptospira), beslenme",B.b8n)
